CREATE TABLE IF NOT EXISTS catering_providers (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',name TEXT NOT NULL,contact_name TEXT,contact_phone TEXT,food_safety_reference TEXT,food_safety_expiry TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,name));
CREATE TABLE IF NOT EXISTS catering_plans (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,title TEXT NOT NULL,service_type TEXT NOT NULL DEFAULT 'meal' CHECK(service_type IN ('meal','refreshments','reception','packed_meal','other')),provider_id INTEGER,audience_id INTEGER,service_at TEXT NOT NULL,delivery_at TEXT,delivery_location TEXT NOT NULL,headcount INTEGER NOT NULL CHECK(headcount>0),menu_summary TEXT,declared_allergens TEXT NOT NULL DEFAULT '[]',notes TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','requested','approved','confirmed','delivered','cancelled','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(provider_id) REFERENCES catering_providers(id) ON DELETE SET NULL,FOREIGN KEY(audience_id) REFERENCES audiences(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS dietary_requirements (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',party_type TEXT NOT NULL CHECK(party_type IN ('user','staff','student','guardian','external')),party_id TEXT NOT NULL,requirement_type TEXT NOT NULL CHECK(requirement_type IN ('allergy','intolerance','religious','ethical','texture','other')),requirement TEXT NOT NULL,severity TEXT NOT NULL DEFAULT 'preference' CHECK(severity IN ('preference','required','critical')),handling_notes TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,party_type,party_id,requirement_type,requirement));
CREATE INDEX IF NOT EXISTS idx_catering_subject ON catering_plans(app_id,subject_component,subject_type,subject_id,status);CREATE INDEX IF NOT EXISTS idx_catering_service ON catering_plans(app_id,service_at,status);CREATE INDEX IF NOT EXISTS idx_dietary_party ON dietary_requirements(app_id,party_type,party_id,status);
